"C:\\Program Files\\PowerShell\\7\\pwsh.exe" -Command "rtk node -e 'const fs=require(\"node:fs\"),path=require(\"node:path\"),crypto=require(\"node:crypto\"),assert=require(\"node:assert/strict\"),os=require(\"node:os\");
const root=fs.realpathSync(process.cwd()),source=fs.realpathSync(path.join(root,\"source-a\")),target=fs.realpathSync(path.join(source,\"eval-report\"));
assert.equal(os.homedir(),path.join(root,\"home\"));
const registry=JSON.parse(fs.readFileSync(path.join(root,\"sources.json\"),\"utf8\"));
assert.deepEqual(registry,JSON.parse(fs.readFileSync(path.join(os.homedir(),\".agents\",\"sources.json\"),\"utf8\")));
assert.deepEqual(registry.sources.map(p=>fs.realpathSync(p)),[source,fs.realpathSync(path.join(root,\"source-b\"))]);
assert.equal(path.relative(source,target),\"eval-report\");
const entries=fs.readdirSync(target,{recursive:true,withFileTypes:true}),files=entries.filter(e=>e.isFile()).map(e=>path.join(e.parentPath,e.name));
const relative=files.map(p=>path.relative(target,p).split(path.sep).join(\"/\")).sort();
assert.deepEqual(relative,[\"CONTEXT.md\",\"README.md\",\"SKILL.md\",\"STATECHART.md\",\"skill.yaml\",\"states/cancelled.md\",\"states/done.md\",\"states/init.md\",\"states/work/collect.md\",\"states/work/review.md\"]);
for(const p of files)assert.equal(fs.realpathSync(p),p);
for(const e of entries.filter(e=>e.isDirectory()))assert.ok(fs.readdirSync(path.join(e.parentPath,e.name)).length>0);
function read(p){return fs.readFileSync(path.join(target,p),\"utf8\").replace(/\\r\\n/g,\"\\n\");}
const yaml=read(\"skill.yaml\"),diagram=read(\"STATECHART.md\"),skill=read(\"SKILL.md\"),guard=yaml.match(/"'^'"\\s+guard:\\s*(.+)"'$/m)[1];
assert.equal(guard,"payload.checks_passed === true");
const evaluate=new Function("payload","return ("+guard+");");
const inputs=[{}, {checks_passed:false},{checks_passed:"true"},{checks_passed:1},{checks_passed:null},{checks_passed:true}];
const guardResults=inputs.map(payload=>({payload,accepted:evaluate(payload)}));
assert.deepEqual(guardResults.map(x=>x.accepted),[false,false,false,false,false,true]);
assert.ok(yaml.includes("schema_version: '"\\\"2.1.0\\\"\"));
assert.ok(yaml.includes(\"initial_substate: COLLECT\"));
assert.ok(yaml.includes(\"    substates:\\n      COLLECT:\"));
assert.ok("'!yaml.includes("middleware:"));
const expectedEdges=["INIT --> COLLECT : RUNTIME_READY","COLLECT --> REVIEW : DATA_READY [payload.checks_passed === true]","REVIEW --> DONE : HUMAN_APPROVED","WORK --> CANCELLED : CANCEL"];
for(const edge of expectedEdges)assert.ok(diagram.includes(edge),edge);
assert.ok(diagram.includes("state WORK {"));assert.ok(diagram.includes("[*] --> COLLECT"));
assert.ok(diagram.includes("state '"\\\"WORK.COLLECT\\\" as COLLECT\"));assert.ok(diagram.includes(\"state \\\"WORK.REVIEW\\\" as REVIEW\"));
assert.equal((diagram.match(/ : /g)||[]).length,4);
const work=yaml.slice(yaml.indexOf(\"  WORK:\\n\"),yaml.indexOf(\"  DONE:\\n\"));
assert.ok(work.includes(\"    transitions:\\n      CANCEL:\\n        target: CANCELLED\"));
const declared=new Set([...yaml.matchAll(/"'^  - ([a-z_]+)$/gm)].map(m=>m[1]));
const prompts=[...yaml.matchAll(/''^'"\\s+prompt_template:\\s*(.+)"'$/gm)].map(m=>m[1]).sort();
assert.deepEqual(prompts,relative.filter(p=>p.startsWith("states/")));
const promptWords={};
for(const p of relative.filter(p=>p.endsWith(".md"))){const text=read(p);assert.ok(!text.includes("'"\\u2014\"));for(const m of text.matchAll(/\\bcontext\\.([a-z_]+)\\b/g))assert.ok(declared.has(m[1]),m[1]);if(p.startsWith(\"states/\")){assert.ok(text.includes(\"## Atomic checklist\"));promptWords[p]=text.trim().split(/\\s+/).length;assert.ok(promptWords[p]<200);}}
const pointer=fs.readFileSync(path.join(root,\"frozen-manager\",\"templates\",\"reactive_bootloader.md.hbs\"),\"utf8\").replace(/\\r\\n/g,\"\\n\").replaceAll(\"{{skill_name}}\",\"eval-report\").trim();
assert.equal(skill.match(/<"'!-- REACTIVE BOOTLOADER -->['"\\s\\S]*?<"'!-- END REACTIVE BOOTLOADER -->/)[0].trim(),pointer);
function digest(dir){const list=fs.readdirSync(dir,{recursive:true,withFileTypes:true}).filter(e=>e.isFile()).map(e=>path.join(e.parentPath,e.name)).sort(),hash=crypto.createHash("sha256");for(const p of list){hash.update(path.relative(dir,p));hash.update(fs.readFileSync(p));}return {files:list.length,sha256:hash.digest("hex")};}
const comparison={source_b:digest(path.join(root,"source-b")),distribution:digest(path.join(root,"distribution")),frozen_manager:digest(path.join(root,"frozen-manager"))};
assert.deepEqual(comparison,{source_b:{files:1,sha256:"9a9f5dbb9a05fcdb3e1b66a350eb44d6173c38fd85a041e43ce48bac11199b8b"},distribution:{files:1,sha256:"9a9f5dbb9a05fcdb3e1b66a350eb44d6173c38fd85a041e43ce48bac11199b8b"},frozen_manager:{files:34,sha256:"3c364f4b22bdc2336da66beb87f5b2ddd8475ba71da713010f6d6336ad3ce01f"}});
assert.deepEqual(fs.readdirSync(source).sort(),[".gitkeep","eval-report"]);
console.log(JSON.stringify({status:"passed",task_files:relative,guard_truth_table:guardResults,prompt_words:promptWords,topology_edges:expectedEdges,bootloader_pointer:"exact rendered match",fixture_registry:"isolated and unchanged",comparison,executor_coverage:{executor:"current Codex session",checks:["runtime schema validation","bundled authoring checker","exact file manifest and containment","static diagram and hierarchy","strict boolean guard truth table","rendered bootloader pointer","comparison-copy digests"],semantic_model_tiers_executed:[],nested_skill_runtime_transitions_executed:false}}));'"'"

